/// Execute set_draft transition on a Registration.
///
/// POST /registrations/:id/transitions/set_draft
pub async fn set_draft_transition(
    axum::extract::State(service): axum::extract::State<Arc<RegistrationService>>,
    axum::extract::Path(id): axum::extract::Path<String>,
    #[cfg(feature = "auth")] axum::Extension(auth): axum::Extension<AuthContext>,
) -> impl axum::response::IntoResponse {
    use axum::{http::StatusCode, Json};

    // Get current entity
    let entity = match service.get_by_id(&id).await {
        Ok(Some(e)) => e,
        Ok(None) => return (StatusCode::NOT_FOUND, Json(ApiResponse::<RegistrationResponseDto>::not_found("Registration", &id))),
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, Json(ApiResponse::<RegistrationResponseDto>::error(e.to_string()))),
    };

    // Check permission (if auth enabled)
    #[cfg(feature = "auth")]
    {
        let allowed_roles = registration_stateTransition::SetDraft.allowed_roles();
        let has_specific_perm = auth.permissions.iter().any(|p| p == "registration:transition:set_draft");
        let has_update_perm = auth.permissions.iter().any(|p| p == "registration:update");
        if !has_specific_perm && !has_update_perm {
            return (StatusCode::FORBIDDEN, Json(ApiResponse::<RegistrationResponseDto>::error("Insufficient permissions for set_draft transition")));
        }
    }

    // Create state machine from entity's actual status and validate transition
    let current_state: registration_stateState = entity.state.to_string().parse()
        .unwrap_or(registration_stateState::default());
    let sm = registration_stateStateMachine::from_state(current_state);
    if !sm.can_transition(registration_stateTransition::SetDraft) {
        return (StatusCode::BAD_REQUEST, Json(ApiResponse::<RegistrationResponseDto>::error("Transition not allowed from current state")));
    }

    // Apply transition via partial update
    let mut fields: HashMap<String, serde_json::Value> = HashMap::new();
    fields.insert("state".to_string(), serde_json::Value::String("Draft".to_string()));

    match service.partial_update(&id, fields).await {
        Ok(Some(updated)) => {
            let response: RegistrationResponseDto = updated.into();
            (StatusCode::OK, Json(ApiResponse::ok(response)))
        }
        Ok(None) => (StatusCode::NOT_FOUND, Json(ApiResponse::<RegistrationResponseDto>::not_found("Registration", &id))),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, Json(ApiResponse::<RegistrationResponseDto>::error(e.to_string()))),
    }
}

