/// Create routes for state transitions.
pub fn create_registration_transition_routes(service: Arc<RegistrationService>) -> Router {
    use axum::routing::post;

    Router::new()
        .route("/registrations/:id/transitions/set_draft", post(set_draft_transition))
        .route("/registrations/:id/transitions/confirm", post(confirm_transition))
        .route("/registrations/:id/transitions/set_done", post(set_done_transition))
        .route("/registrations/:id/transitions/cancel", post(cancel_transition))
        .with_state(service)
}
